/**
 * Generated by quail.
 *
 * Interaction-state visual baselines for https://www.spritecloud.com/test-automation. For the primary CTA,
 * screenshots default / hover / focus states and diffs against
 * committed PNGs. Catches subtle regressions invisible to viewport
 * baselines.
 *
 * Filter: `npx playwright test --grep @kind:visual-state`
 */
import { test, expect } from '@playwright/test'
import { INTERACTION_STATES } from '../prims'

test.describe.configure({ mode: 'parallel' })
test.describe('Spritecloud — interaction-state visual @ https://www.spritecloud.com/test-automation', () => {
  test('@kind:visual-state @smoke primary CTA across states', async ({ page }) => {
    await page.goto('https://www.spritecloud.com/test-automation')
    await page.waitForLoadState('networkidle').catch(() => {})
    const target = page.getByRole('link').first()
    if (await target.count() === 0) {
      test.skip(true, 'no primary CTA detected on this page')
      return
    }

    for (const state of INTERACTION_STATES) {
      switch (state) {
        case 'hover':
          await target.hover().catch(() => {})
          break
        case 'focus':
          await target.focus().catch(() => {})
          break
        default:
          break
      }
      await expect(target).toHaveScreenshot(`spritecloud-cta-${state}.png`, {
        maxDiffPixelRatio: 0.02,
        animations: 'disabled',
      })
    }
  })
})
